package org.schoolkernel.workspace;

import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.node.ArrayNode;
import tools.jackson.databind.node.ObjectNode;

/** No cascade: every literal dependency, cancellation and policy removal is an explicit reviewed choice. */
@Service
public class DefinitionRemovalService {
    static final Map<String,String> COLLECTIONS=Map.of("Period","periods","Subject","subjects","Teacher","teachers","Cohort","cohorts","Room","rooms","Lesson","lessons","RoomAssignment","roomAssignments");
    private final WorkspaceStore repository;
    private final ObjectMapper json;
    private final DefinitionEntityService entities;
    private final DefinitionRequirementService requirements;
    private final DefinitionGridService grid;
    public DefinitionRemovalService(WorkspaceStore repository,ObjectMapper json,DefinitionEntityService entities,DefinitionRequirementService requirements,DefinitionGridService grid){this.repository=repository;this.json=json;this.entities=entities;this.requirements=requirements;this.grid=grid;}

    public ObjectNode inspect(String ifMatch,JsonNode target){return inspection(checked(ifMatch),target);}
    public ObjectNode preview(String ifMatch,JsonNode request){
        WorkspaceAggregate current=checked(ifMatch);ObjectNode candidate=operation(current,request);ObjectNode result=inspection(current,request.path("target"));result.put("token",token(current,request));result.set("definitionAfter",candidate.path("definitionDraft").path("definition"));result.set("editingContextAfter",candidate.path("definitionDraft").path("editingContext"));result.set("issues",candidate.path("definitionDraft").path("issues"));result.set("changes",changes(current.document().path("definitionDraft"),candidate.path("definitionDraft")));return result;
    }
    @Transactional public WorkspaceAggregate save(String ifMatch,JsonNode envelope){
        WorkspaceAggregate current=checked(ifMatch);if(!(envelope instanceof ObjectNode)||!envelope.propertyNames().equals(Set.of("request","token"))||!envelope.path("token").isTextual()||!token(current,envelope.path("request")).equals(envelope.path("token").asString("")))throw problem("STALE_REMOVAL_PREVIEW","Review the exact complete removal against the current saved draft. No change was committed.");
        ObjectNode document=operation(current,envelope.path("request"));if(repository.replace(current.version(),WorkspaceState.DEFINITION_DRAFT,WorkspaceState.DEFINITION_DRAFT,document).isEmpty())throw new WorkspaceProblem(HttpStatus.PRECONDITION_FAILED,"STALE_WORKSPACE_VERSION","The workspace changed. No resolution, cancellation or removal was committed.");return repository.load();
    }
    private ObjectNode inspection(WorkspaceAggregate current,JsonNode target){
        validateTarget(current.document().path("definitionDraft"),target);JsonNode draft=current.document().path("definitionDraft"),definition=draft.path("definition");String type=target.path("type").asString(""),id=target.path("id").asString("");ObjectNode result=json.createObjectNode().put("workspaceVersion",current.version());result.set("target",target.deepCopy());result.set("item",type.equals("Series")?requirements.context((ObjectNode)draft).path(id):find(definition.path(COLLECTIONS.get(type)),id));
        ArrayNode references=result.putArray("references");for(Reference ref:references(draft,type,id))references.addObject().put("key",ref.key()).put("ownerType",ref.ownerType()).put("ownerId",ref.ownerId()).put("field",ref.field()).put("array",ref.array()).put("required",ref.required()).set("value",ref.item().path(ref.field()).deepCopy());
        Set<String> owned=requirementOwners(draft,type,id);ArrayNode members=result.putArray("ownedOccurrences");for(JsonNode lesson:definition.path("lessons"))if(owned.contains(lesson.path("seriesId").asString(""))||type.equals("Lesson")&&id.equals(lesson.path("id").asString("")))members.add(lesson);
        result.set("historicalPlacements",historical(draft,type,id));result.put("hasSource",hasSource(draft,type,id));return result;
    }
    private ObjectNode operation(WorkspaceAggregate current,JsonNode request){
        if(!(request instanceof ObjectNode)||!request.propertyNames().equals(Set.of("target","resolutions","cancelLessonIds","removeRuleIds","removeRequirementIds"))||!request.path("resolutions").isArray())throw problem("INVALID_REMOVAL_OPERATION","Supply target, explicit dependency resolutions, selected cancellations and selected rule removals only.");
        ObjectNode document=((ObjectNode)current.document()).deepCopy(),draft=(ObjectNode)document.path("definitionDraft"),definition=(ObjectNode)draft.path("definition");JsonNode target=request.path("target");validateTarget(draft,target);String type=target.path("type").asString(""),id=target.path("id").asString("");materializeOwnedContext(draft,type,id);Set<String> cancellations=strings(request.path("cancelLessonIds")),rules=strings(request.path("removeRuleIds")),removedRequirements=strings(request.path("removeRequirementIds"));
        Set<String> permittedLessons=new LinkedHashSet<>(),permittedRules=new LinkedHashSet<>(),permittedRequirements=new LinkedHashSet<>();for(Reference ref:references(draft,type,id)){if(ref.ownerType().equals("Lesson"))permittedLessons.add(ref.ownerId());if(ref.ownerType().equals("RoomAssignment"))permittedRules.add(ref.ownerId());if(ref.ownerType().startsWith("Requirement"))permittedRequirements.add(ref.ownerId());}if(type.equals("Series"))for(JsonNode lesson:definition.path("lessons"))if(id.equals(lesson.path("seriesId").asString("")))permittedLessons.add(lesson.path("id").asString(""));if(type.equals("Lesson"))permittedLessons.add(id);if(type.equals("RoomAssignment"))permittedRules.add(id);
        permittedRequirements.addAll(requirementOwners(draft,type,id));for(JsonNode lesson:definition.path("lessons"))if(permittedRequirements.contains(lesson.path("seriesId").asString("")))permittedLessons.add(lesson.path("id").asString(""));
        if(!permittedLessons.containsAll(cancellations)||!permittedRules.containsAll(rules)||!permittedRequirements.containsAll(removedRequirements))throw problem("UNRELATED_REMOVAL_SELECTION","Only the target or its displayed dependent occurrences/rules may be cancelled or removed here.");
        for(String requirement:removedRequirements)for(JsonNode lesson:definition.path("lessons"))if(requirement.equals(lesson.path("seriesId").asString(""))&&!cancellations.contains(lesson.path("id").asString("")))throw problem("EXPLICIT_CANCELLATION_REQUIRED","Removing dependent requirement "+requirement+" requires explicitly selecting every member occurrence for cancellation.");
        if(type.equals("Lesson")&&!cancellations.contains(id))throw problem("EXPLICIT_CANCELLATION_REQUIRED","Select the target occurrence explicitly for cancellation before removing it.");
        Map<String,Reference> dependencies=new LinkedHashMap<>();for(Reference ref:references(draft,type,id))dependencies.put(ref.key(),ref);Set<String> resolved=new HashSet<>();Set<String> affectedSeries=new LinkedHashSet<>();
        for(JsonNode choice:request.path("resolutions")){
            String key=choice.path("key").asString(""),mode=choice.path("mode").asString("");Reference ref=dependencies.get(key);if(ref==null||!resolved.add(key)||!(choice instanceof ObjectNode)||!choice.propertyNames().equals(mode.equals("replace")?Set.of("key","mode","replacementId"):Set.of("key","mode")))throw problem("INVALID_DEPENDENCY_CHOICE","Each displayed dependency may have one explicit supported resolution only.");
            if(ref.ownerType().startsWith("Requirement")&&removedRequirements.contains(ref.ownerId())||ref.ownerType().equals("Lesson")&&cancellations.contains(ref.ownerId())||ref.ownerType().equals("RoomAssignment")&&(rules.contains(ref.ownerId())||type.equals("RoomAssignment")&&id.equals(ref.ownerId())))throw problem("CONTRADICTORY_REMOVAL_CHOICE","Do not also edit a row explicitly selected for cancellation/removal.");
            if(mode.equals("home")&&type.equals("Room")&&ref.ownerType().equals("RoomAssignment")&&ref.field().equals("allowedRoomIds")){ref.item().remove("allowedRoomIds");ref.item().put("useHomeRoom",true);continue;}
            if(!Set.of("remove","replace").contains(mode))throw problem("INVALID_DEPENDENCY_CHOICE","Choose explicit replacement, removal of an optional/set reference, or a room rule's home-room target.");
            String replacement=choice.path("replacementId").asString("");if(ref.field().equals("seriesId")&&mode.equals("replace"))affectedSeries.add(replacement);if(mode.equals("replace")&&(!choice.path("replacementId").isTextual()||replacement.equals(id)||!replacementExists(draft,type,replacement)))throw problem("UNKNOWN_REPLACEMENT","Choose another declared "+type+" identity for "+key+". No change was committed.");
            if(!ref.array()&&ref.required()&&mode.equals("remove"))throw problem("REQUIRED_DEPENDENCY_UNRESOLVED","Replace required "+key+" or explicitly cancel/remove its owning row.");
            if(ref.array()){ArrayNode values=json.createArrayNode();for(JsonNode value:ref.item().path(ref.field()))if(!id.equals(value.asString("")))values.add(value.deepCopy());else if(mode.equals("replace")&&!contains(ref.item().path(ref.field()),replacement))values.add(replacement);ref.item().set(ref.field(),values);}else if(mode.equals("remove"))ref.item().remove(ref.field());else ref.item().put(ref.field(),replacement);
        }
        for(JsonNode choice:request.path("resolutions")){Reference ref=dependencies.get(choice.path("key").asString(""));if(ref.ownerType().equals("Lesson")&&Set.of("periodLock","roomLock").contains(ref.field())){ObjectNode locks=draft.withObject("editingContext").withObject("authoredLocks").withObject(ref.ownerId());if(ref.item().has(ref.field()))locks.set(ref.field(),ref.item().path(ref.field()).deepCopy());else locks.remove(ref.field());}}
        for(JsonNode lesson:definition.path("lessons"))if(cancellations.contains(lesson.path("id").asString(""))&&lesson.path("seriesId").isTextual())affectedSeries.add(lesson.path("seriesId").asString(""));
        ObjectNode inferred=requirements.context(draft);for(String lesson:cancellations){reserve(draft,"Lesson",lesson);remove(definition,"lessons",lesson);if(draft.path("editingContext").path("authoredLocks").isObject())((ObjectNode)draft.path("editingContext").path("authoredLocks")).remove(lesson);}for(String rule:rules){reserve(draft,"RoomAssignment",rule);remove(definition,"roomAssignments",rule);}
        if(type.equals("Series")){if(draft.path("editingContext").path("requirements").isObject())((ObjectNode)draft.path("editingContext").path("requirements")).remove(id);}else if(!type.equals("Lesson")&&!type.equals("RoomAssignment"))remove(definition,COLLECTIONS.get(type),id);else if(type.equals("RoomAssignment")&&!rules.contains(id))remove(definition,"roomAssignments",id);
        reserve(draft,type,id);
        for(String requirement:removedRequirements){if(draft.path("editingContext").path("requirements").isObject())((ObjectNode)draft.path("editingContext").path("requirements")).remove(requirement);reserve(draft,"Series",requirement);}
        for(String series:affectedSeries)if((!type.equals("Series")||!series.equals(id))&&!removedRequirements.contains(series)){
            ObjectNode row=(ObjectNode)inferred.path(series).deepCopy();int count=0;for(JsonNode lesson:definition.path("lessons"))if(series.equals(lesson.path("seriesId").asString("")))count++;row.put("count",count);for(String cancelled:cancellations)if(row.path("exceptions").isObject())((ObjectNode)row.path("exceptions")).remove(cancelled);draft.withObject("editingContext").withObject("requirements").set(series,row);
        }
        ObjectNode originalContext=requirements.context((ObjectNode)current.document().path("definitionDraft"));
        for(JsonNode choice:request.path("resolutions")){
            Reference ref=dependencies.get(choice.path("key").asString(""));if(!ref.ownerType().equals("Lesson"))continue;
            JsonNode lesson=find(definition.path("lessons"),ref.ownerId());if(lesson==null||!lesson.path("seriesId").isTextual())continue;JsonNode context=draft.path("editingContext").path("requirements").path(lesson.path("seriesId").asString(""));if(!context.isObject())continue;
            List<String> selected=ref.field().equals("seriesId")?DefinitionRequirementService.SHARED:DefinitionRequirementService.SHARED.contains(ref.field())?List.of(ref.field()):List.of();
            ArrayNode exceptions=((ObjectNode)context).withObject("exceptions").withArray(ref.ownerId());
            if(ref.field().equals("seriesId")){JsonNode original=find(current.document().path("definitionDraft").path("definition").path("lessons"),ref.ownerId());for(JsonNode field:originalContext.path(original.path("seriesId").asString("")).path("exceptions").path(ref.ownerId()))if(!contains(exceptions,field.asString("")))exceptions.add(field.deepCopy());}
            for(String field:selected)if(contains(context.path("mixedFields"),field)||!lesson.path(field).equals(context.path("defaults").path(field)))if(!contains(exceptions,field))exceptions.add(field);
        }
        List<Reference> remaining=references(draft,type,id);if(!remaining.isEmpty())throw problem("UNRESOLVED_REMOVAL_DEPENDENCIES","Resolve every remaining reference: "+String.join("; ",remaining.stream().map(Reference::key).toList())+". No change was committed.");
        for(JsonNode policy:definition.path("roomAssignments"))if(permittedRules.contains(policy.path("id").asString(""))&&policy.path("allowedRoomIds").isArray()&&policy.path("allowedRoomIds").isEmpty())throw problem("EMPTY_ROOM_POLICY_TARGET","The last allowed room requires a replacement, explicit home-room target, or explicit policy removal.");
        entities.refreshAllEntityIssues(draft);grid.refreshIssues(draft);draft.put("draftRevision",DefinitionDraftService.revision(definition));ObjectNode history=json.createObjectNode();history.set("target",target.deepCopy());history.set("cancelLessonIds",request.path("cancelLessonIds").deepCopy());history.set("removeRuleIds",request.path("removeRuleIds").deepCopy());history.set("removeRequirementIds",request.path("removeRequirementIds").deepCopy());history.set("resolutions",request.path("resolutions").deepCopy());draft.withArray("removalOperations").add(history);return document;
    }
    private List<Reference> references(JsonNode draft,String type,String id){
        List<Reference> result=new ArrayList<>();JsonNode definition=draft.path("definition");
        if(type.equals("Period")){reference(result,(ObjectNode)definition,"School",definition.path("schoolId").asString(""),"reservedPeriodIds",true,false,id);for(String collection:List.of("teachers","cohorts","rooms"))for(JsonNode row:definition.path(collection)){String owner=collection.equals("teachers")?"Teacher":collection.equals("cohorts")?"Cohort":"Room";reference(result,(ObjectNode)row,owner,row.path("id").asString(""),"availablePeriodIds",true,false,id);if(!collection.equals("rooms"))reference(result,(ObjectNode)row,owner,row.path("id").asString(""),"undesirablePeriodIds",true,false,id);}}
        if(type.equals("Subject"))for(JsonNode row:definition.path("teachers"))reference(result,(ObjectNode)row,"Teacher",row.path("id").asString(""),"qualifiedSubjectIds",true,false,id);
        if(type.equals("Teacher")||type.equals("Room"))for(JsonNode row:definition.path("cohorts"))reference(result,(ObjectNode)row,"Cohort",row.path("id").asString(""),type.equals("Teacher")?"curatorTeacherId":"homeRoomId",false,false,id);
        for(JsonNode row:definition.path("lessons")){String owner=row.path("id").asString("");for(String field:lessonFields(type))reference(result,(ObjectNode)row,"Lesson",owner,field,Set.of("preferredRoomIds","undesirablePeriodIds").contains(field),Set.of("subjectId","cohortId","teacherId").contains(field),id);}
        for(JsonNode row:definition.path("roomAssignments")){String field=type.equals("Subject")?"subjectId":type.equals("Teacher")?"teacherId":type.equals("Room")?"allowedRoomIds":null;if(field!=null)reference(result,(ObjectNode)row,"RoomAssignment",row.path("id").asString(""),field,type.equals("Room"),type.equals("Subject"),id);}
        for(var entry:requirements.context((ObjectNode)draft).properties()){
            ObjectNode row=draft.path("editingContext").path("requirements").has(entry.getKey())?(ObjectNode)draft.path("editingContext").path("requirements").path(entry.getKey()):(ObjectNode)entry.getValue();String field=type.equals("Subject")?"subjectId":type.equals("Cohort")?"cohortId":null;if(field!=null)reference(result,row,"Requirement",entry.getKey(),field,false,true,id);
            if(row.path("defaults").isObject())for(String shared:lessonFields(type))if(DefinitionRequirementService.SHARED.contains(shared))reference(result,(ObjectNode)row.path("defaults"),"Requirement defaults",entry.getKey(),shared,Set.of("preferredRoomIds","undesirablePeriodIds").contains(shared),shared.equals("teacherId"),id);
        }
        return result;
    }
    private void materializeOwnedContext(ObjectNode draft,String type,String id){
        ObjectNode inferred=requirements.context(draft);for(String owner:requirementOwners(draft,type,id))if(!draft.path("editingContext").path("requirements").has(owner))draft.withObject("editingContext").withObject("requirements").set(owner,inferred.path(owner).deepCopy());
    }
    private Set<String> requirementOwners(JsonNode draft,String type,String id){
        Set<String> result=new LinkedHashSet<>();if(type.equals("Series")){result.add(id);return result;}
        for(Reference ref:references(draft,type,id))if(ref.ownerType().startsWith("Requirement"))result.add(ref.ownerId());else if(ref.ownerType().equals("Lesson")){JsonNode row=find(draft.path("definition").path("lessons"),ref.ownerId());if(row.path("seriesId").isTextual())result.add(row.path("seriesId").asString(""));}
        if(type.equals("Lesson")){JsonNode row=find(draft.path("definition").path("lessons"),id);if(row.path("seriesId").isTextual())result.add(row.path("seriesId").asString(""));}return result;
    }
    private static List<String> lessonFields(String type){return switch(type){case "Period"->List.of("periodLock","undesirablePeriodIds");case "Subject"->List.of("subjectId");case "Teacher"->List.of("teacherId");case "Cohort"->List.of("cohortId");case "Room"->List.of("preferredRoomIds","roomLock");case "Series"->List.of("seriesId");default->List.of();};}
    private static void reference(List<Reference> result,ObjectNode item,String type,String owner,String field,boolean array,boolean required,String id){JsonNode value=item.path(field);if(array?contains(value,id):value.isTextual()&&id.equals(value.asString("")))result.add(new Reference(type+":"+owner+":"+field,type,owner,field,array,required,item));}
    private boolean replacementExists(ObjectNode draft,String type,String id){return type.equals("Series")?requirements.context(draft).has(id):find(draft.path("definition").path(COLLECTIONS.get(type)),id)!=null;}
    private void validateTarget(JsonNode draft,JsonNode target){if(!(target instanceof ObjectNode)||!target.propertyNames().equals(Set.of("type","id"))||!target.path("id").isTextual()||!target.path("type").isTextual()||!COLLECTIONS.containsKey(target.path("type").asString(""))&&!"Series".equals(target.path("type").asString("")))throw problem("INVALID_REMOVAL_TARGET","Choose a declared period, subject, teacher, class, room, occurrence, policy or weekly requirement.");String type=target.path("type").asString(""),id=target.path("id").asString("");if(type.equals("Series")?!requirements.context((ObjectNode)draft).has(id):find(draft.path("definition").path(COLLECTIONS.get(type)),id)==null)throw problem("REMOVAL_TARGET_MISSING","The selected item is no longer in the saved draft; refresh and choose again.");}
    private void reserve(ObjectNode draft,String type,String id){for(JsonNode row:draft.path("removedIdentities"))if(type.equals(row.path("ownerType").asString(""))&&id.equals(row.path("id").asString("")))return;draft.withArray("removedIdentities").addObject().put("ownerType",type).put("id",id).put("hasSource",hasSource(draft,type,id));}
    private boolean hasSource(JsonNode draft,String type,String id){JsonNode source=sourceDefinition(draft);if(type.equals("Series")){for(JsonNode lesson:source.path("lessons"))if(id.equals(lesson.path("seriesId").asString("")))return true;return false;}return find(source.path(COLLECTIONS.get(type)),id)!=null;}
    private ArrayNode historical(JsonNode draft,String type,String id){ArrayNode result=json.createArrayNode();JsonNode source=sourceDefinition(draft);Set<String> ids=new HashSet<>(),owned=requirementOwners(draft,type,id);JsonNode selectedPolicy=type.equals("RoomAssignment")?find(draft.path("definition").path("roomAssignments"),id):null;for(JsonNode lesson:source.path("lessons")){boolean matches=owned.contains(lesson.path("seriesId").asString(""))||selectedPolicy!=null&&selectedPolicy.path("subjectId").equals(lesson.path("subjectId"))&&(!selectedPolicy.has("teacherId")||selectedPolicy.path("teacherId").equals(lesson.path("teacherId")))||type.equals("Lesson")&&id.equals(lesson.path("id").asString(""));for(String field:lessonFields(type))if(contains(lesson.path(field),id)||id.equals(lesson.path(field).asString("")))matches=true;if(matches)ids.add(lesson.path("id").asString(""));}for(JsonNode placement:draft.path("sourceDocument").path("acceptedBaseline").path("result").path("timetable").path("assignments"))if(ids.contains(placement.path("lessonId").asString(""))||type.equals("Period")&&id.equals(placement.path("periodId").asString(""))||type.equals("Room")&&id.equals(placement.path("roomId").asString("")))result.add(placement.deepCopy());return result;}
    static JsonNode sourceDefinition(JsonNode draft){JsonNode source=draft.path("sourceDocument");return source.has("initialDefinition")?source.path("initialDefinition"):source.path("acceptedBaseline").path("definition");}
    private ArrayNode changes(JsonNode before,JsonNode after){ArrayNode result=json.createArrayNode();for(String field:List.of("definition","editingContext","removedIdentities"))if(!before.path(field).equals(after.path(field))){ObjectNode row=result.addObject().put("scope",field);row.set("before",before.path(field).deepCopy());row.set("after",after.path(field).deepCopy());}return result;}
    private WorkspaceAggregate checked(String ifMatch){WorkspaceAggregate current=repository.load();ImportService.requireMatchingVersion(ifMatch,current);if(current.state()!=WorkspaceState.DEFINITION_DRAFT)throw problem("INVALID_WORKSPACE_TRANSITION","Guided removal requires an open definition draft. No change was committed.");return current;}
    private static String token(WorkspaceAggregate current,JsonNode request){ObjectNode value=((ObjectNode)current.document()).deepCopy();value.put("previewVersion",current.version());value.set("removalOperation",request);return DefinitionDraftService.revision(value);}
    private static Set<String> strings(JsonNode values){if(!values.isArray())throw problem("INVALID_REMOVAL_SELECTION","Selections must be arrays of unique declared identifiers.");Set<String> ids=new LinkedHashSet<>();for(JsonNode value:values)if(!value.isTextual()||!ids.add(value.asString("")))throw problem("INVALID_REMOVAL_SELECTION","Selections must be arrays of unique declared identifiers.");return ids;}
    private static void remove(ObjectNode definition,String collection,String id){ArrayNode rows=(ArrayNode)definition.path(collection);for(int i=rows.size()-1;i>=0;i--)if(id.equals(rows.get(i).path("id").asString("")))rows.remove(i);}
    private static JsonNode find(JsonNode rows,String id){for(JsonNode row:rows)if(id.equals(row.path("id").asString("")))return row;return null;}
    private static boolean contains(JsonNode values,String id){for(JsonNode value:values)if(id.equals(value.asString("")))return true;return false;}
    private static WorkspaceProblem problem(String code,String message){return new WorkspaceProblem(HttpStatus.CONFLICT,code,message);}
    private record Reference(String key,String ownerType,String ownerId,String field,boolean array,boolean required,ObjectNode item){}
}
